<template><PageShell title="Organization Audit Log" subtitle="Review membership, role, fleet, dispatch, and organization changes scoped to your tenant." icon="lucide:history" eyebrow="Organization Management"><section class="overflow-hidden rounded-3xl border border-base-300 bg-base-100 shadow-sm dark:border-white/10 dark:bg-[#071829]"><div class="flex gap-3 border-b border-base-300 p-4"><input v-model="search" class="min-w-0 flex-1 rounded-xl border border-base-300 bg-base-100 px-4 py-2.5 text-sm dark:bg-white/5 dark:text-white" placeholder="Search activity..." @keyup.enter="load(1)"/><button class="rounded-xl border border-base-300 px-4 text-xs font-black" @click="load(1)">Search</button></div><div v-if="loading" class="py-20 text-center text-sm text-slate-400">Loading audit activity...</div><div v-else class="divide-y divide-base-300 dark:divide-white/5"><article v-for="i in merged" :key="`${i.source}-${i.id}`" class="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><div><p class="text-sm font-black text-slate-800 dark:text-white/75">{{ pretty(i.action) }}</p><p class="mt-1 text-xs text-slate-400">{{ i.actor_name||'System' }} · {{ pretty(i.entity_type) }}</p></div><p class="text-xs font-bold text-slate-500">{{ format(i.created_at) }}</p></article><p v-if="!merged.length" class="py-16 text-center text-sm text-slate-400">No matching audit activity.</p></div></section></PageShell></template>
<script setup>import{computed,onMounted,ref}from'vue';import PageShell from '@/components/management/PageShell.vue';import{fetchOrganizationAudit}from'@/services/organizationCompletion';const search=ref(''),items=ref([]),rbac=ref([]),loading=ref(false),merged=computed(()=>[...items.value.map(x=>({...x,source:'audit'})),...rbac.value.map(x=>({...x,source:'rbac'}))].sort((a,b)=>new Date(String(b.created_at).replace(' ','T'))-new Date(String(a.created_at).replace(' ','T'))).slice(0,100));const pretty=v=>String(v||'').replaceAll('.',' › ').replaceAll('_',' ');const format=v=>v?new Date(String(v).replace(' ','T')).toLocaleString():'—';async function load(page=1){loading.value=true;try{const d=await fetchOrganizationAudit({search:search.value,page});items.value=d.items||[];rbac.value=d.rbac_items||[]}finally{loading.value=false}}onMounted(()=>load())</script>
